def calculate_scholarship(grades: list[int], leader: str, west: str, papers: int) -> int:
    avg = grades[0]
    class_eval = grades[1]
    scholarship = 0
    if avg > 80 and papers >= 1:
        scholarship += 8000
    if avg > 85 and class_eval > 80:
        scholarship += 4000
    if avg > 90:
        scholarship += 2000
    if avg > 85 and west == 'Y':
        scholarship += 1000
    if class_eval > 80 and leader == 'Y':
        scholarship += 850
    return scholarship

def decode(encoded: str, original: str, message: str) -> str:
    # Check length consistency
    if len(encoded) != len(original):
        return "Failed"
    mapping = {}
    for e, o in zip(encoded, original):
        if e in mapping:
            if mapping[e] != o:
                return "Failed"  # Contradiction
        else:
            mapping[e] = o
    # Ensure all 26 uppercase letters are represented in the mapping
    if len(mapping) < 26:
        return "Failed"
    # Decode the message
    decoded_chars = []
    for ch in message:
        if ch not in mapping:
            return "Failed"
        decoded_chars.append(mapping[ch])
    return "".join(decoded_chars)

def generate_numbers(n, rules):
    """Generates unique numbers from n by applying digit transformation rules."""
    start = str(n)
    queue = [start]
    visited = {start}
    while queue:
        cur = queue.pop(0)
        for i, ch in enumerate(cur):
            d = int(ch)
            for x, y in rules:
                if d == x:
                    new_num = cur[:i] + str(y) + cur[i+1:]
                    if new_num not in visited:
                        visited.add(new_num)
                        queue.append(new_num)
    return len(visited)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on
    the given statements while ignoring any statements about the day of the week.

    Parameters:
        scenario (str): The name of the participant being tested as the potential criminal.
        liar_count (set): A set of names of participants who are assumed to be liars.
        statements (dict): A dictionary mapping participant names to lists of their statements.
        days_of_week (set): A set of strings representing the days of the week.

    Returns:
        bool: True if the scenario is consistent with the statements, False otherwise.
    """
    # Helper to determine if a statement concerns a day of the week
    def is_day_statement(sentence: str) -> bool:
        words = set(word.strip(".,'\"").lower() for word in sentence.split())
        return any(day.lower() in words for day in days_of_week)

    # Helper to parse a single statement
    def parse_statement(speaker: str, sentence: str) -> (str, bool) | None:
        sentence = sentence.strip()
        if not sentence:
            return None
        # Remove trailing period
        if sentence.endswith('.'):
            sentence = sentence[:-1]
        words = sentence.split()
        if not words:
            return None

        # Detect subject
        if words[0].upper() in ("I", "IM"):
            subject = speaker
            # Determine guilt reference
            # e.g., "I am guilty" or "I am not guilty"
            if len(words) >= 3:
                if words[1].lower() == 'am':
                    if words[2].lower() == 'guilty':
                        return subject, True
                    if len(words) >= 4 and words[2].lower() == 'not' and words[3].lower() == 'guilty':
                        return subject, False
        else:
            # Expect pattern: "<NAME> is guilty" or "<NAME> is not guilty"
            subject = words[0].strip(".,'\"")
            if len(words) >= 3 and words[1].lower() == 'is':
                if words[2].lower() == 'guilty':
                    return subject, True
                if len(words) >= 4 and words[2].lower() == 'not' and words[3].lower() == 'guilty':
                    return subject, False

        return None

    # Check all statements
    for speaker, stmt_list in statements.items():
        for sentence in stmt_list:
            # Skip if it's a day-related statement
            if is_day_statement(sentence):
                continue
            parsed = parse_statement(speaker, sentence)
            if parsed is None:
                # If statement cannot be parsed, skip it
                continue
            subject, declared_guilty = parsed
            actual_guilty = (subject == scenario)
            truth = (declared_guilty == actual_guilty)

            if speaker in liar_count:
                # Liars must make false statements
                if truth:
                    return False
            else:
                # Truth-tellers must make true statements
                if not truth:
                    return False

    return True

def catalan_number(n: int) -> int:
    """Compute the nth Catalan number using dynamic programming."""
    if n < 0:
        raise ValueError("n must be non-negative")
    c = [0] * (n + 1)
    c[0] = 1
    for i in range(1, n + 1):
        total = 0
        for j in range(i):
            total += c[j] * c[i - 1 - j]
        c[i] = total
    return c[n]

def remaining_trees_after_clearing(l: int, areas: list) -> int:
    if not areas:
        return l
    # Merge intervals treating them as [start, end) where end is exclusive
    # Sort by start
    sorted_areas = sorted(areas, key=lambda x: x[0])
    merged = []
    for start, end in sorted_areas:
        if not merged:
            merged.append([start, end])
        else:
            last_start, last_end = merged[-1]
            if start <= last_end:  # Overlap or adjacent
                merged[-1][1] = max(last_end, end)
            else:
                merged.append([start, end])
    # Sum total cleared length
    cleared = sum(end - start for start, end in merged)
    # Ensure not negative result
    return max(0, l - cleared)

def min_remaining_space(V: int, n: int, volumes: list) -> int:
    """
    Calculate the minimum remaining space in a box after trying to fit a number of items with given volumes.
    """
    # Use 0/1 knapsack to find the maximum volume that can be filled
    dp = [0] * (V + 1)
    for vol in volumes:
        if vol > V:
            continue
        for cap in range(V, vol - 1, -1):
            if dp[cap] < dp[cap - vol] + vol:
                dp[cap] = dp[cap - vol] + vol
    max_filled = max(dp)
    return V - max_filled

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    dp = [0] * (m + 1)
    dp[0] = 1
    for ai in a:
        prefix = [0] * (m + 1)
        prefix[0] = dp[0] % MOD
        for i in range(1, m + 1):
            prefix[i] = (prefix[i - 1] + dp[i]) % MOD
        new_dp = [0] * (m + 1)
        for j in range(m + 1):
            left = j - ai - 1
            if left >= 0:
                val = prefix[j] - prefix[left]
            else:
                val = prefix[j]
            new_dp[j] = val % MOD
        dp = new_dp
    return dp[m] % MOD

def find_most_unhappy_day(schedule) -> int:
    max_over = 0
    most_unhappy_day = 0
    for i, (school, extra) in enumerate(schedule):
        total = school + extra
        if total > 8:
            over = total - 8
            if over > max_over:
                max_over = over
                most_unhappy_day = i + 1
    return most_unhappy_day
